// ── CASTLE ROCK WALK — Edinburgh Castle from street level ──

svg += `<defs>
  <linearGradient id="lg-crw" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#0A1220' : '#5A6A78'}"/>
    <stop offset="30%" stop-color="${isN ? '#141E2E' : sc.sky1}"/>
    <stop offset="70%" stop-color="${isN ? '#1A2838' : '#7A98B0'}"/>
    <stop offset="100%" stop-color="${isN ? '#1E2A3A' : sc.sky2}"/>
  </linearGradient>
  <linearGradient id="lg-crw-hill" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#4A7A3A"/>
    <stop offset="100%" stop-color="#5A9A4A"/>
  </linearGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-crw)"/>`;

// ── DRAMATIC CLOUDS (heavy, moody Edinburgh sky) ──
for (let i = 0; i < 8; i++) {
  const ccx = (w * 0.05 + i * w * 0.15 + mt * 2.5) % (w + 100) - 50;
  const ccy = h * 0.05 + Math.sin(i * 1.5) * h * 0.06;
  const ccr = 45 + Math.sin(i * 2.1) * 18;
  const cdark = isN ? '#1A2030' : (i < 4 ? '#5A6068' : '#8898A0');
  const cop = isN ? 0.5 : 0.5 + Math.sin(i * 0.9) * 0.15;
  svg += `<ellipse cx="${ccx}" cy="${ccy}" rx="${ccr}" ry="${ccr * 0.38}" fill="${cdark}" opacity="${cop}"/>`;
  svg += `<ellipse cx="${ccx + ccr * 0.3}" cy="${ccy + 3}" rx="${ccr * 0.65}" ry="${ccr * 0.28}" fill="${cdark}" opacity="${cop * 0.75}"/>`;
}
// Light break through clouds (that Edinburgh golden light)
if (!isN) {
  svg += `<ellipse cx="${w * 0.45}" cy="${h * 0.15}" rx="${w * 0.12}" ry="${h * 0.06}" fill="#FFEECC" opacity="0.06"/>`;
  svg += `<ellipse cx="${w * 0.45}" cy="${h * 0.18}" rx="${w * 0.08}" ry="${h * 0.04}" fill="#FFEECC" opacity="0.04"/>`;
}

// ── CASTLE ROCK (the dramatic crag) ──
const rockX = w * 0.55;
const rockY = bY - 20;
const rockH = h * 0.4;

// Rock face (dark volcanic basalt)
svg += `<path d="M${rockX - w * 0.15} ${rockY} Q${rockX - w * 0.08} ${rockY - rockH * 0.3} ${rockX - w * 0.02} ${rockY - rockH * 0.7} Q${rockX + w * 0.05} ${rockY - rockH * 0.85} ${rockX + w * 0.12} ${rockY - rockH * 0.75} Q${rockX + w * 0.2} ${rockY - rockH * 0.5} ${rockX + w * 0.28} ${rockY}" fill="#4A4A42" stroke="#3A3A32" stroke-width="${ol * 0.6}"/>`;
// Rock texture
for (let i = 0; i < 6; i++) {
  const rtx = rockX - w * 0.1 + i * w * 0.06;
  const rty = rockY - rockH * (0.2 + Math.sin(i * 1.7) * 0.15);
  svg += `<line x1="${rtx}" y1="${rty}" x2="${rtx + 8}" y2="${rty + 12}" stroke="#3A3A32" stroke-width="0.8" opacity="0.3"/>`;
}

// ── GREEN HILLSIDE (sweeping grass below the castle) ──
svg += `<path d="M${rockX - w * 0.2} ${rockY + 5} Q${rockX} ${rockY - 15} ${rockX + w * 0.3} ${rockY + 5} L${rockX + w * 0.3} ${bY} L${rockX - w * 0.2} ${bY} Z" fill="url(#lg-crw-hill)" stroke="#3A6A2A" stroke-width="${ol * 0.4}"/>`;
// Grass texture on hillside
for (let i = 0; i < 12; i++) {
  const ghx = rockX - w * 0.15 + i * w * 0.04;
  const ghy = rockY + Math.sin(i * 1.5) * 3 + i * 1.5;
  const gsw = Math.sin(mt * 0.8 + i * 0.6) * 1;
  svg += `<line x1="${ghx}" y1="${ghy}" x2="${ghx + gsw}" y2="${ghy - 4}" stroke="#4A8A3A" stroke-width="1" stroke-linecap="round" opacity="0.4"/>`;
}

// ═══ EDINBURGH CASTLE (on top of the crag) ═══
const cx = rockX + w * 0.02;
const cy = rockY - rockH * 0.75;

// Half Moon Battery (curved wall)
svg += `<path d="M${cx - 30} ${cy + 25} Q${cx - 40} ${cy + 10} ${cx - 35} ${cy - 5} L${cx + 10} ${cy - 5} L${cx + 10} ${cy + 25}" fill="${sc.bld}" stroke="#4A4238" stroke-width="${ol}"/>`;

// Main castle buildings (clustered)
svg += `<rect x="${cx - 25}" y="${cy - 25}" width="35" height="30" rx="1" fill="${sc.bld}" stroke="#4A4238" stroke-width="${ol}"/>`;
svg += `<rect x="${cx + 12}" y="${cy - 35}" width="20" height="40" rx="1" fill="#5A4F42" stroke="#4A4238" stroke-width="${ol}"/>`;
svg += `<rect x="${cx - 10}" y="${cy - 40}" width="15" height="18" rx="1" fill="${sc.bld}" stroke="#4A4238" stroke-width="${ol}"/>`;

// Battlements
for (let i = 0; i < 7; i++) {
  const bx = cx - 27 + i * 8;
  svg += `<rect x="${bx}" y="${cy - 29}" width="4" height="4" fill="${sc.bld}" stroke="#4A4238" stroke-width="${ol * 0.4}"/>`;
}

// Flag on pole
svg += `<line x1="${cx + 5}" y1="${cy - 40}" x2="${cx + 5}" y2="${cy - 58}" stroke="#4A4238" stroke-width="1"/>`;
const flagWave = Math.sin(mt * 2) * 3;
svg += `<path d="M${cx + 5} ${cy - 58} L${cx + 18 + flagWave} ${cy - 54} L${cx + 5} ${cy - 50}" fill="#1A3A8A" stroke="#1A2A5A" stroke-width="${ol * 0.3}"/>`;
// Cross on flag
svg += `<line x1="${cx + 5}" y1="${cy - 54}" x2="${cx + 18 + flagWave}" y2="${cy - 54}" stroke="#FFF" stroke-width="0.8"/>`;
svg += `<line x1="${cx + 11 + flagWave * 0.5}" y1="${cy - 58}" x2="${cx + 11 + flagWave * 0.5}" y2="${cy - 50}" stroke="#FFF" stroke-width="0.8"/>`;

// Castle windows
const cWinPos = [[-18, cy - 18], [-8, cy - 18], [2, cy - 18], [16, cy - 28], [16, cy - 15], [-4, cy - 35]];
for (let i = 0; i < 6; i++) {
  const wxp = cx + cWinPos[i][0];
  const wyp = cWinPos[i][1];
  const pulse = Math.sin(mt * 1.5 + i * 1.1) * 0.5 + 0.5;
  svg += `<rect x="${wxp}" y="${wyp}" width="5" height="7" rx="2" fill="${isN ? `rgba(255,200,100,${0.35 + pulse * 0.45})` : 'rgba(80,80,60,0.2)'}" stroke="#4A4238" stroke-width="${ol * 0.3}"/>`;
  if (isN) svg += `<ellipse cx="${wxp + 2.5}" cy="${wyp + 3.5}" rx="8" ry="6" fill="rgba(255,200,100,0.03)"/>`;
}

// ── Defensive walls running down the hill ──
svg += `<path d="M${cx - 35} ${cy + 25} Q${cx - 45} ${rockY - rockH * 0.2} ${rockX - w * 0.12} ${rockY + 2}" fill="none" stroke="#5A5040" stroke-width="${ol * 0.8}"/>`;
svg += `<path d="M${cx + 32} ${cy + 5} Q${cx + 40} ${rockY - rockH * 0.15} ${rockX + w * 0.2} ${rockY + 5}" fill="none" stroke="#5A5040" stroke-width="${ol * 0.7}"/>`;

// ═══ STREET LEVEL ═══

// Road surface
svg += `<rect x="0" y="${bY - 5}" width="${w}" height="${h - bY + 5}" fill="#5A5A52"/>`;

// Pavement (sidewalk) in foreground
svg += `<rect x="0" y="${bY + 15}" width="${w}" height="${h - bY - 15}" fill="#8A8A82" stroke="#7A7A72" stroke-width="0.5"/>`;
// Pavement texture (flagstones)
for (let i = 0; i < 12; i++) {
  const fx = i * (w / 12);
  svg += `<line x1="${fx}" y1="${bY + 15}" x2="${fx}" y2="${h}" stroke="#7A7A72" stroke-width="0.5" opacity="0.3"/>`;
}
svg += `<line x1="0" y1="${bY + 30}" x2="${w}" y2="${bY + 30}" stroke="#7A7A72" stroke-width="0.5" opacity="0.3"/>`;

// Kerb
svg += `<line x1="0" y1="${bY + 14}" x2="${w}" y2="${bY + 14}" stroke="#6A6A62" stroke-width="2"/>`;

// ── IRON RAILINGS ──
const railY = bY + 5;
svg += `<line x1="${w * 0.15}" y1="${railY}" x2="${w * 0.75}" y2="${railY}" stroke="#2A2A2A" stroke-width="2"/>`;
svg += `<line x1="${w * 0.15}" y1="${railY + 10}" x2="${w * 0.75}" y2="${railY + 10}" stroke="#2A2A2A" stroke-width="1.5"/>`;
for (let i = 0; i < 15; i++) {
  const rx = w * 0.15 + i * (w * 0.6 / 15);
  svg += `<line x1="${rx}" y1="${railY - 3}" x2="${rx}" y2="${railY + 13}" stroke="#2A2A2A" stroke-width="1.2"/>`;
  // Pointed tops
  svg += `<polygon points="${rx - 1.5},${railY - 3} ${rx},${railY - 6} ${rx + 1.5},${railY - 3}" fill="#2A2A2A"/>`;
}

// ── PARKED BICYCLES (at the railing) ──
const bikes = [{x: w * 0.3, col: '#333'}, {x: w * 0.38, col: '#333'}, {x: w * 0.46, col: '#DD3366'}]; // Pink bike!
for (let b = 0; b < 3; b++) {
  const bx = bikes[b].x, by2 = railY + 4;
  // Wheels
  svg += `<circle cx="${bx - 6}" cy="${by2 + 4}" r="7" fill="none" stroke="${bikes[b].col}" stroke-width="1.2"/>`;
  svg += `<circle cx="${bx + 8}" cy="${by2 + 4}" r="7" fill="none" stroke="${bikes[b].col}" stroke-width="1.2"/>`;
  // Frame
  svg += `<path d="M${bx - 6} ${by2 + 4} L${bx + 1} ${by2 - 4} L${bx + 8} ${by2 + 4}" fill="none" stroke="${bikes[b].col}" stroke-width="1.5"/>`;
  svg += `<line x1="${bx + 1}" y1="${by2 - 4}" x2="${bx - 4}" y2="${by2 - 4}" stroke="${bikes[b].col}" stroke-width="1.5"/>`;
  // Handlebars
  svg += `<line x1="${bx - 4}" y1="${by2 - 6}" x2="${bx - 4}" y2="${by2 - 2}" stroke="${bikes[b].col}" stroke-width="1"/>`;
  // Spokes (simplified)
  svg += `<line x1="${bx - 6}" y1="${by2 - 3}" x2="${bx - 6}" y2="${by2 + 11}" stroke="${bikes[b].col}" stroke-width="0.3" opacity="0.4"/>`;
  svg += `<line x1="${bx - 13}" y1="${by2 + 4}" x2="${bx + 1}" y2="${by2 + 4}" stroke="${bikes[b].col}" stroke-width="0.3" opacity="0.4"/>`;
}

// ── CARS on the road (small, animated) ──
for (let i = 0; i < 3; i++) {
  const carX = (w * 0.1 + i * w * 0.35 + mt * 15) % (w + 40) - 20;
  const carY2 = bY + 2 + i * 3;
  const carCols = ['#CC3333', '#4A6A8A', '#E8E0D0'];
  svg += `<rect x="${carX - 10}" y="${carY2 - 6}" width="20" height="8" rx="2" fill="${carCols[i]}" stroke="#2A2A2A" stroke-width="${ol * 0.3}" opacity="0.6"/>`;
  svg += `<rect x="${carX - 5}" y="${carY2 - 9}" width="10" height="5" rx="1.5" fill="${carCols[i]}" opacity="0.5"/>`;
  svg += `<circle cx="${carX - 6}" cy="${carY2 + 2}" r="2" fill="#222" opacity="0.5"/>`;
  svg += `<circle cx="${carX + 6}" cy="${carY2 + 2}" r="2" fill="#222" opacity="0.5"/>`;
}

// ── Bus (Edinburgh Lothian bus, green/gold) ──
const busX = (w * 0.5 + mt * 8) % (w + 60) - 30;
const busY2 = bY + 1;
svg += `<rect x="${busX - 14}" y="${busY2 - 14}" width="28" height="16" rx="2" fill="#8A2010" stroke="#5A1008" stroke-width="${ol * 0.4}" opacity="0.55"/>`;
svg += `<rect x="${busX - 12}" y="${busY2 - 12}" width="24" height="6" rx="1" fill="rgba(180,220,255,0.3)" opacity="0.5"/>`;
svg += `<circle cx="${busX - 8}" cy="${busY2 + 2}" r="2.5" fill="#222" opacity="0.5"/>`;
svg += `<circle cx="${busX + 8}" cy="${busY2 + 2}" r="2.5" fill="#222" opacity="0.5"/>`;

// ── SMALL STROLLER on pavement ──
const stX = w * 0.18, stY = bY + 25;
// Wheels
svg += `<circle cx="${stX - 5}" cy="${stY + 5}" r="3" fill="#333" stroke="#222" stroke-width="0.5"/>`;
svg += `<circle cx="${stX + 8}" cy="${stY + 5}" r="3" fill="#333" stroke="#222" stroke-width="0.5"/>`;
// Frame
svg += `<line x1="${stX - 5}" y1="${stY + 5}" x2="${stX}" y2="${stY - 8}" stroke="#333" stroke-width="1.5"/>`;
svg += `<line x1="${stX + 8}" y1="${stY + 5}" x2="${stX + 3}" y2="${stY - 8}" stroke="#333" stroke-width="1.5"/>`;
// Hood
svg += `<path d="M${stX - 2} ${stY - 10} Q${stX + 1} ${stY - 18} ${stX + 6} ${stY - 10}" fill="#2A2A2A" stroke="#1A1A1A" stroke-width="1"/>`;
// Blanket hint (pink)
svg += `<rect x="${stX - 1}" y="${stY - 6}" width="6" height="8" rx="2" fill="#E8B8C8" opacity="0.6"/>`;
// Handle
svg += `<line x1="${stX}" y1="${stY - 8}" x2="${stX - 3}" y2="${stY - 16}" stroke="#333" stroke-width="1.5" stroke-linecap="round"/>`;

// ── STREET LAMP ──
const slx2 = w * 0.08;
svg += `<line x1="${slx2}" y1="${bY + 15}" x2="${slx2}" y2="${bY - 30}" stroke="#3A3A3A" stroke-width="2.5"/>`;
svg += `<path d="M${slx2} ${bY - 30} Q${slx2 + 8} ${bY - 32} ${slx2 + 10} ${bY - 28}" fill="none" stroke="#3A3A3A" stroke-width="2"/>`;
const lampGlow = isN ? 0.6 : 0.15;
svg += `<circle cx="${slx2 + 10}" cy="${bY - 26}" r="4" fill="#FFE088" opacity="${lampGlow}"/>`;
if (isN) svg += `<circle cx="${slx2 + 10}" cy="${bY - 26}" r="20" fill="#FFE088" opacity="0.04"/>`;

// ── BUILDING FACADE (left edge, Victorian sandstone) ──
svg += `<rect x="0" y="${h * 0.1}" width="${w * 0.06}" height="${h * 0.9}" fill="#6A5A4A" stroke="#5A4A3A" stroke-width="${ol * 0.5}"/>`;
for (let i = 0; i < 4; i++) {
  const wy = h * 0.15 + i * h * 0.15;
  svg += `<rect x="${w * 0.01}" y="${wy}" width="${w * 0.04}" height="${h * 0.08}" rx="1" fill="${isN ? 'rgba(255,200,100,0.2)' : 'rgba(100,100,80,0.15)'}" stroke="#5A4A3A" stroke-width="${ol * 0.3}"/>`;
}
// Decorative stonework
svg += `<rect x="0" y="${h * 0.1}" width="${w * 0.065}" height="3" fill="#7A6A5A"/>`;
svg += `<rect x="0" y="${h * 0.25}" width="${w * 0.065}" height="2" fill="#7A6A5A"/>`;

if (isN) {
  // Moon through clouds
  svg += `<circle cx="${w * 0.75}" cy="${h * 0.1}" r="14" fill="#E0DCD0" opacity="0.5"/>`;
  svg += `<circle cx="${w * 0.75 + 4}" cy="${h * 0.1 - 3}" r="11" fill="#0A1220" opacity="0.8"/>`;
}
